using UnityEngine;
public sealed class SettingsHoverAudio:MonoBehaviour{
 AudioSource controlSource;AudioClip volumeRelease,tutorialClick;float volumeGain,tutorialGain;int volumeStart,tutorialStart;
 AudioSource iconSource,textSource;AudioClip spin,tick;float spinGain=.25f,tickGain=.18f,nextIcon,nextText;
 static SettingsHoverAudio For(Component owner){var menu=owner.GetComponentInParent<PauseMenu>();if(menu==null)menu=FindAnyObjectByType<PauseMenu>();var host=menu!=null?menu.gameObject:owner.gameObject;var a=host.GetComponent<SettingsHoverAudio>();return a!=null?a:host.AddComponent<SettingsHoverAudio>();}
 AudioSource Source(string name){var go=new GameObject(name);go.transform.SetParent(transform,false);var s=go.AddComponent<AudioSource>();s.playOnAwake=false;s.spatialBlend=0;s.ignoreListenerPause=true;s.priority=96;return s;}
 static float Gain(AudioClip clip,float target,float fallback){if(clip==null)return fallback;clip.LoadAudioData();var data=new float[clip.samples*clip.channels];if(!clip.GetData(data,0))return fallback;float peak=0;foreach(float x in data)peak=Mathf.Max(peak,Mathf.Abs(x));return Mathf.Min(.55f,target/Mathf.Max(.01f,peak));}
 void Awake(){controlSource=Source("SettingsControlSound");volumeRelease=Resources.Load<AudioClip>("VolumeRelease");tutorialClick=Resources.Load<AudioClip>("TutorialButtonClick");volumeGain=Gain(volumeRelease,.13f,.25f);tutorialGain=Gain(tutorialClick,.12f,.25f);volumeStart=FirstFrame(volumeRelease);tutorialStart=FirstFrame(tutorialClick);iconSource=Source("SettingsIconHoverSound");textSource=Source("SettingsTextHoverSound");spin=Resources.Load<AudioClip>("SettingsHoverSpin");tick=Resources.Load<AudioClip>("SettingsHoverTick");spinGain=Gain(spin,.12f,.25f);tickGain=Gain(tick,.05f,.18f);}
 public static void PlayIcon(Component owner){var a=For(owner);if(a.spin==null||Time.unscaledTime<a.nextIcon)return;a.nextIcon=Time.unscaledTime+.15f;a.iconSource.clip=a.spin;a.iconSource.volume=a.spinGain;a.iconSource.Play();}
 public static void PlayText(Component owner){foreach(var group in owner.GetComponentsInParent<CanvasGroup>())if(!group.interactable)return;var a=For(owner);if(a.tick==null||Time.unscaledTime<a.nextText)return;a.nextText=Time.unscaledTime+.075f;a.textSource.clip=a.tick;a.textSource.volume=a.tickGain;a.textSource.Play();}
 public static void PlayVolumeRelease(Component owner){var a=For(owner);if(a.volumeRelease==null)return;a.controlSource.clip=a.volumeRelease;a.controlSource.volume=a.volumeGain;a.controlSource.timeSamples=a.volumeStart;a.controlSource.Play();}
 public static void PlayTutorialClick(Component owner){var a=For(owner);if(a.tutorialClick==null)return;a.controlSource.clip=a.tutorialClick;a.controlSource.volume=a.tutorialGain;a.controlSource.timeSamples=a.tutorialStart;a.controlSource.Play();}
 static int FirstFrame(AudioClip c){if(c==null)return 0;var data=new float[c.samples*c.channels];if(!c.GetData(data,0))return 0;float peak=0;foreach(float v in data)peak=Mathf.Max(peak,Mathf.Abs(v));for(int i=0;i<data.Length;i++)if(Mathf.Abs(data[i])>peak*.02f)return i/c.channels;return 0;}
}